pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 wei, 1e30);
        vm.assume(actor.balance >= amount);

        // deposit via the payable fallback using a low-level call
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool dok, ) = address(c).call{value: amount}("");
        assertTrue(dok);

        // first withdraw must succeed
        vm.prank(actor);
        bool ok1;
        try c.withdraw() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        // RULE: any later withdraw from the same actor must also succeed
        // (reference zeroed the balance; sending 0 always succeeds)
        vm.prank(actor);
        bool ok2;
        try c.withdraw() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2);
    }
}

