pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: any actor without code (so the low-level ETH send in
        // withdraw always succeeds for the reference) and any positive amount.
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1 ether);

        // Fund the actor and deposit `amount` through the fallback.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk);

        // The reference zeroes the caller's balance after a successful withdraw;
        // the mutant leaves it at `amount` (> 0).
        vm.prank(actor);
        try c.withdraw() {
            assertTrue(c.balances(actor) == 0);
        } catch {
            assertTrue(c.balances(actor) == 0);
        }
    }
}

