        amount = bound(amount, 1 wei, 100 ether);
        Attacker a = new Attacker();
        a.setTarget(address(c));
        vm.deal(address(a), amount);
        vm.prank(address(a));
        c.fallback{value: amount}();
        vm.prank(address(a));
        bool ok;
