pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1000 ether);

        // adversarial counterparty: reverts whenever it receives a nonzero value
        PickyReceiver attacker = new PickyReceiver();

        // attacker deposits `amount` into c (deposit path is benign)
        vm.deal(address(attacker), amount);
        attacker.deposit(c, amount);
        assertEq(address(c).balance, amount);

        // attacker withdraws; a successful completion must not revert
        vm.prank(address(attacker));
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: a funded account can always withdraw without revert.
        // Reference C sends the balance; the PickyReceiver accepts it and withdraw completes.
        // The mutant zeroes the balance first and sends 0 wei... but its send succeeds,
        // so the distinguishing observable is the payout: assert via revert flag AND
        // that the deposited funds actually left the contract.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract PickyReceiver {
    fallback() external payable {
        if (msg.value > 0) revert();
    }

    function deposit(C c, uint256 amt) external payable {
        address(c).call{value: amt}("");
    }
}

