pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reentrant attacker;

    function setUp() public { c = new C(); attacker = new Reentrant(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < address(this).balance + 1 ether);
        amount = bound(amount, 1, 1 ether);

        // fund the attacker's account, then credit it in C via the payable fallback
        address actor = address(attacker);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);

        attacker.setTarget(address(c));
        uint256 balBefore = address(c).balance;
        vm.assume(balBefore >= amount);

        // attacker's withdraw: its receive() re-enters c.withdraw() during the external call
        bool ok;
        vm.prank(actor);
        try c.withdraw() { ok = true; } catch { ok = false; }

        // General rule: a withdrawal whose callee re-enters withdraw can never complete
        // (the reentrancy lock makes the reentrant call fail, reverting the outer call).
        assertTrue(!ok);
    }
}

contract Reentrant {
    address public target;
    bool public attacked;

    function setTarget(address t) external { target = t; }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            (bool s, ) = target.call("");
            s; // reentrant withdraw; reverts bubble up in the guarded contract
        }
    }
}
}
